565		if err == nil || !strings.Contains(err.Error(), `context["user.name"]`) {
566			t.Fatalf("escaped dot key: err=%v", err)
567		}
568	
569		// 重复字段同样按统一规则定位；名字渲染为 JSON 字符串。
570		_, err = ParseContext([]byte(`{"user.name":1,"user.name":2}`))
571		if err == nil || !strings.Contains(err.Error(), `context["user.name"]: duplicate field "user.name"`) {
572			t.Fatalf("duplicate dotted key: err=%v", err)
573		}
574		// 转义形式与直接字符是同名字段：重复检查与定位都按解码后的文字。
575		_, err = ParseContext([]byte(`{"x.y":1,"x.y":2}`))
576		if err == nil || !strings.Contains(err.Error(), `context["x.y"]: duplicate field "x.y"`) {
577			t.Fatalf("duplicate escaped key: err=%v", err)
578		}
579		_, err = ParseContext([]byte(`{"":1,"":2}`))
580		if err == nil || !strings.Contains(err.Error(), `context[""]: duplicate field ""`) {
581			t.Fatalf("duplicate empty key: err=%v", err)
582		}
583	
584		// 配置附加字段名为 meta.info，其中嵌套对象的 owner 重复：
585		// 应显示 config.flags[0]["meta.info"].owner。
586		rawConfig := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
587			"meta.info":{"owner":"a","owner":"b"}}]}`
588		_, err = ParseConfig([]byte(rawConfig))
589		if err == nil || !strings.Contains(err.Error(), `config.flags[0]["meta.info"].owner`) ||
590			!strings.Contains(err.Error(), "duplicate field") {
591			t.Fatalf("nested duplicate under dotted extra field: err=%v", err)
592		}
593		// 附加字段数组元素里的点号字段名同样加方括号。
594		rawConfig = `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
595			"tags":[{"v":1},{"a.b":1,"a.b":2}]}]}`
596		_, err = ParseConfig([]byte(rawConfig))
597		if err == nil || !strings.Contains(err.Error(), `config.flags[0].tags[1]["a.b"]`) ||
598			!strings.Contains(err.Error(), "duplicate field") {
599			t.Fatalf("duplicate in extra array element: err=%v", err)
600		}
601		// 顶层附加的点号字段名。
602		_, err = ParseConfig([]byte(`{"flags":[],"x.y":1,"x.y":2}`))
603		if err == nil || !strings.Contains(err.Error(), `config["x.y"]: duplicate field "x.y"`) {
604			t.Fatalf("duplicate dotted top-level extra field: err=%v", err)
605		}
606	
607		// 点号字段名的值含不完整 Unicode 转义：错误位置用方括号包住字段名。
608		_, err = ParseContext([]byte(`{"user.name":"\uD800"}`))
609		if err == nil || !strings.Contains(err.Error(), `context["user.name"]`) ||
610			!strings.Contains(err.Error(), "does not form a complete character") {
611			t.Fatalf("bad escape under dotted key: err=%v", err)
612		}
