698	func TestContextOutOfRangeNumbersAreTypeErrors(t *testing.T) {
699		// 1 后接 400 个 0：远超 float64 可表示范围的合法 JSON 整数。它与 1e400、
700		// -1e400 一样是语法合法的 JSON 数字——用户把应为字符串的属性写成数字时，
701		// 必须报该属性的类型错误，而不是被解码阶段当成 JSON 语法错误。
702		hugeInt := "1" + strings.Repeat("0", 400)
703		cases := []struct {
704			name         string
705			raw          string
706			wantAttr     string
707			topLevelOnly bool // 对象/数组值的错误不得指向内部成员
708		}{
709			{"exponent overflow", `{"plan":1e400}`, "context.plan", false},
710			{"negative exponent overflow", `{"plan":-1e400}`, "context.plan", false},
711			{"400-digit integer", `{"plan":` + hugeInt + `}`, "context.plan", false},
712			{"object holding big number", `{"plan":{"inner":1e400}}`, "context.plan", true},
713			{"array holding big numbers", `{"plan":[1e400,-1e400]}`, "context.plan", true},
714			{"nested object then later scalar", `{"a":"x","obj":{"inner":` + hugeInt + `},"b":2}`, "context.obj", true},
715		}
716		for _, tc := range cases {
717			t.Run(tc.name, func(t *testing.T) {
718				_, err := ParseContext([]byte(tc.raw))
719				if err == nil {
720					t.Fatalf("ParseContext(%s): expected error, got nil", tc.raw)
721				}
722				msg := err.Error()
723				if strings.Contains(msg, "invalid JSON") {
724					t.Fatalf("a legal big number must not be reported as a JSON syntax error: %q", msg)
725				}
726				if !strings.Contains(msg, tc.wantAttr) || !strings.Contains(msg, "value must be a string") {
727					t.Fatalf("err=%q, want %s string-type error", msg, tc.wantAttr)
728				}
729				if tc.topLevelOnly && strings.Contains(msg, "inner") {
730					t.Fatalf("object/array value error must stay on the top-level attribute: %q", msg)
731				}
732			})
733		}
734	
735		// 规则不引用该属性：上下文校验独立于配置与求值，同样拒绝并按属性类型错误报告。
736		_, err := ParseContext([]byte(`{"unreferenced":1e400}`))
737		if err == nil || !strings.Contains(err.Error(), "context.unreferenced") ||
738			!strings.Contains(err.Error(), "value must be a string") ||
739			strings.Contains(err.Error(), "invalid JSON") {
740			t.Fatalf("unreferenced big-number attr: err=%v", err)
741		}
742	}
