778		// 两处都是大数字时同样取原文第一处。
779		_, err = ParseContext([]byte(`{"a":1e400,"b":-1e400}`))
780		if err == nil || !strings.Contains(err.Error(), "context.a") ||
781			strings.Contains(err.Error(), "context.b") {
782			t.Fatalf("two big numbers: err=%v want context.a only", err)
783		}
784	}
