814	func TestQuotedBigNumberStaysString(t *testing.T) {
815		hugeInt := "1" + strings.Repeat("0", 400)
816		// 同样的数字文本加上引号后就是普通字符串，按原文参与 eq 匹配，
817		// 不能被数值化、改写或继续拒绝。
818		cfg := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
819			{"id":"r-exp","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"1e400"}]},
820			{"id":"r-neg","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"-1e400"}]},
821			{"id":"r-int","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"` + hugeInt + `"}]}]}]}`
822		for _, tc := range []struct {
823			ctxRaw string
824			ruleID string
825			reason EvalReason
826		}{
827			{`{"plan":"1e400"}`, "r-exp", EvalRule},
828			{`{"plan":"-1e400"}`, "r-neg", EvalRule},
829			{`{"plan":"` + hugeInt + `"}`, "r-int", EvalRule},
830			{`{"plan":"1e401"}`, "", EvalDefault}, // 不做数值换算："1e401" != "1e400"
831		} {
832			got := eval(t, cfg, "f", tc.ctxRaw)
833			if got.Reason != tc.reason ||
834				(tc.reason == EvalRule && (got.RuleID == nil || *got.RuleID != tc.ruleID)) {
835				t.Fatalf("ctx=%s: got %+v, want reason=%s rule=%s", tc.ctxRaw, got, tc.reason, tc.ruleID)
836			}
837		}
838	
839		// 1e400 与 1 后接 400 个 0 在数值上相等，但字符串写法不同：不得互相命中。
840		cfgInt := `{"flags":[{"key":"g","enabled":true,"default":false,"rules":[
841			{"id":"r-int","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"` + hugeInt + `"}]}]}]}`
842		if got := eval(t, cfgInt, "g", `{"plan":"1e400"}`); got.Reason != EvalDefault {
843			t.Fatalf("numerically equal spellings must not match as strings: %+v", got)
844		}
845		if got := eval(t, cfgInt, "g", `{"plan":"`+hugeInt+`"}`); got.Reason != EvalRule {
846			t.Fatalf("identical spelling must match verbatim: %+v", got)
847		}
848	
849		// ParseContext 保留引号内的原文，不做任何转换。
850		ctx := mustParseContext(t, `{"plan":"1e400"}`)
851		if v, ok := ctx.Get("plan"); !ok || v != "1e400" {
852			t.Fatalf("quoted big number was rewritten: %q %v", v, ok)
853		}
854	}
