1317			{"default when no rule matches", "f", `{"plan":"free","region":"eu"}`,
1318				EvalResult{Key: "f", Value: true, Reason: EvalDefault, RuleID: nil}},
1319			{"disabled flag stays false", "off", `{"plan":"pro","tier":"a","region":"cn"}`,
1320				EvalResult{Key: "off", Value: false, Reason: EvalDisabled, RuleID: nil}},
1321		}
1322		for _, variant := range extraFieldConfigVariants() {
1323			for _, tc := range cases {
1324				t.Run(variant.name+"/"+tc.name, func(t *testing.T) {
1325					got := eval(t, variant.raw, tc.key, tc.ctx)
1326					if !got.Equals(tc.want) {
1327						t.Fatalf("got %+v, want %+v", got, tc.want)
1328					}
1329				})
1330			}
1331		}
1332	}
