1357		cases := []struct {
1358			name string
1359			raw  string
1360			want string
1361		}{
1362			{"after exponent overflow", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
1363				"meta":{"n":1e400,"n":2}}]}`, `config.flags[0].meta.n`},
1364			{"after 400-digit integer", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
1365				"meta":{"n":` + hugeInt + `,"n":2}}]}`, `config.flags[0].meta.n`},
1366			{"top-level extra object", `{"flags":[],"meta":{"n":1e400,"n":2}}`, `config.meta.n`},
1367			{"nested inside extra array", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
1368				"tags":[{"n":1e400,"n":2}]}]}`, `config.flags[0].tags[0].n`},
1369		}
