784	// evalFailure 运行 evaluate 并要求失败：退出码非零、stdout 为空。返回 stderr 原文。
785	func evalFailure(t *testing.T, h *harness, key string) string {
786		t.Helper()
787		var stdout, stderr bytes.Buffer
788		if code := run(h.evalArgs(key), &stdout, &stderr); code == 0 {
789			t.Fatalf("key %q: expected non-zero exit, stdout=%q", key, stdout.String())
790		}
791		if stdout.Len() != 0 {
792			t.Fatalf("key %q: stdout must be empty on error, got %q", key, stdout.String())
793		}
794		return stderr.String()
795	}
