797	// escapeNameConfig 用给定的 key/id 写法（JSON 字符串内容，不含引号）拼出一份
798	// 合法配置：一个启用的开关，一条 eq 规则（plan=pro 命中，value=true），
799	// default=false。只有名称写法可变，业务内容固定。
800	func escapeNameConfig(keyJSON, idJSON string) string {
801		return `{"flags":[{"key":"` + keyJSON + `","enabled":true,"default":false,"rules":[` +
802			`{"id":"` + idJSON + `","value":true,"conditions":[` +
803			`{"attribute":"plan","op":"eq","value":"pro"}]}]}]}`
804	}
