997	
998	// TestCLIEvaluateSimilarNamesStayDistinct 验证名称的精确区分：大小写不同、前后
999	// 空白不同、外观相似但字符序列不同的名字（é 预组合 vs e+组合符、西里尔 а vs
1000	// 拉丁 a）既不合并也不互认重复；请求一个仅相似、实际不存在的开关键时报告
1001	// 未找到且 stdout 为空，而不是选择近似名称。
1002	func TestCLIEvaluateSimilarNamesStayDistinct(t *testing.T) {
1003		// 每个合法 key 用不同的 default 值标记，求值结果可区分究竟选中了谁。
1004		// 注意 café（预组合 é，U+00E9）与 cafe\u0301（e + 组合符 U+0301）、
1005		// p\u0430y（西里尔 а，U+0430）与拉丁 pay 都是不同的名字。
1006		config := `{"flags":[
1007			{"key":"feature-a","enabled":true,"default":false,"rules":[]},
1008			{"key":"Feature-A","enabled":true,"default":true,"rules":[]},
1009			{"key":" feature-a","enabled":true,"default":true,"rules":[]},
1010			{"key":"feature-a ","enabled":true,"default":true,"rules":[]},
1011			{"key":"café","enabled":true,"default":false,"rules":[]},
1012			{"key":"cafe\u0301","enabled":true,"default":true,"rules":[]},
1013			{"key":"p\u0430y","enabled":true,"default":false,"rules":[]}]}`
1014		h := newHarness(t, config, `{}`)
1015	
1016		// 相似名字共存于同一份配置而不被误判为重复，且各自按精确名称求值。
1017		existing := []struct {
1018			key   string
1019			value bool
1020		}{
1021			{"feature-a", false},
1022			{"Feature-A", true},
1023			{" feature-a", true},
1024			{"feature-a ", true},
1025			{"café", false},
1026			{"cafe\u0301", true}, // e + 组合符 U+0301，与预组合的 "café" 不是同一个名字
1027			{"p\u0430y", false},  // 西里尔 а（U+0430）
1028		}
1029		for _, tc := range existing {
1030			got, _ := evalSuccess(t, h, tc.key)
1031			if got["key"] != tc.key || got["value"] != tc.value || got["reason"] != "default" {
1032				t.Fatalf("key %q: unexpected payload: %v", tc.key, got)
1033			}
1034		}
1035	
1036		// 仅大小写、空白或字符序列相似、实际不存在的 key 必须报告未找到。
1037		missing := []string{
1038			"feature-A",
1039			"FEATURE-A",
1040			"feature-a  ", // 两个尾随空格
1041			"  feature-a", // 两个前导空格
1042			"pay",         // 纯拉丁字母，配置里只有含西里尔 а 的 "p\u0430y"
1043			"cafe",        // 无重音符
1044			"café ",       // 尾随空格
1045		}
1046		for _, key := range missing {
1047			msg := evalFailure(t, h, key)
1048			if !strings.Contains(msg, "not found") {
1049				t.Fatalf("key %q: stderr=%q, want not found", key, msg)
1050			}
1051		}
1052	}
1053	
1054	// TestCLIEvaluateBackslashTextIsNotReDecoded 验证带有反斜杠、看起来像 Unicode
1055	// 转义的普通文本不会被再次解码：JSON 里的 "\\u00E9" 解码为普通文本 u00E9，
1056	// 它与真正的 "café" 是两个不同的合法名字，互不冲突、互不选中。
1057	func TestCLIEvaluateBackslashTextIsNotReDecoded(t *testing.T) {
1058		// 第一个开关的 key/id 都是带反斜杠的普通文本；若被再次解码，两个开关的
1059		// key 都会变成 "café" 而被判重复——配置合法本身即证明没有二次解码。
1060		config := `{"flags":[
1061			{"key":"caf\\u00E9","enabled":true,"default":false,"rules":[
1062				{"id":"r-\\uD83D\\uDE80","value":true,"conditions":[
1063					{"attribute":"plan","op":"eq","value":"pro"}]}]},
1064			{"key":"café","enabled":true,"default":true,"rules":[]}]}`
1065		h := newHarness(t, config, `{"plan":"pro"}`)
1066	
1067		// 解码后的 "café" 选中第二个开关，而不是反斜杠文本那一个。
1068		got, _ := evalSuccess(t, h, "café")
1069		if got["key"] != "café" || got["value"] != true || got["reason"] != "default" || got["ruleId"] != nil {
1070			t.Fatalf("decoded name must select the real café flag: %v", got)
1071		}
1072	
1073		// 反斜杠文本按原样是一个独立 key：结果中的名称保持原文，不变成转义解码
1074		// 后的字符。
1075		literalKey := `caf\u00E9`
1076		literalID := `r-\uD83D\uDE80`
1077		got, _ = evalSuccess(t, h, literalKey)
1078		if got["key"] != literalKey || got["value"] != true ||
1079			got["reason"] != "rule" || got["ruleId"] != literalID {
1080			t.Fatalf("backslash text must stay a literal name: %v", got)
1081		}
1082	}
1083	
1084	// TestCLIEvaluateNameErrorPrecedencePreserved 沿用现有错误优先级：文档级检查
1085	// （非法 Unicode 转义、同一对象重复字段）先于业务唯一性（重复开关键）报告。
1086	func TestCLIEvaluateNameErrorPrecedencePreserved(t *testing.T) {
1087		cases := []struct {
1088			name    string
1089			config  string
1090			wantSub string
1091			notSub  string
1092		}{
1093			{
1094				// flags[1] 同一对象内重复声明 key（第二次写法解码后与 flags[0]
1095				// 冲突）：报字段重复，而不是开关键重复。
1096				"duplicate field beats duplicate flag key",
1097				`{"flags":[
1098					{"key":"café","enabled":true,"default":false,"rules":[]},
1099					{"key":"other","key":"caf\u00E9","enabled":true,"default":false,"rules":[]}]}`,
1100				`config.flags[1].key: duplicate field "key"`,
1101				"duplicate flag key",
1102			},
1103			{
1104				// flags[1] 的 key 与 flags[0] 解码后冲突，同时其条件值含孤立
1105				// 代理项转义：报非法转义，而不是开关键重复。
1106				"invalid escape beats duplicate flag key",
1107				`{"flags":[
1108					{"key":"café","enabled":true,"default":false,"rules":[]},
1109					{"key":"caf\u00E9","enabled":true,"default":false,"rules":[
1110						{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\uD800"}]}]}]}`,
1111				"invalid Unicode escape",
1112				"duplicate flag key",
1113			},
1114		}
1115		for _, tc := range cases {
1116			t.Run(tc.name, func(t *testing.T) {
1117				h := newHarness(t, tc.config, `{}`)
1118				msg := evalFailure(t, h, "café")
1119				if !strings.Contains(msg, tc.wantSub) {
1120					t.Fatalf("stderr=%q, want substring %q", msg, tc.wantSub)
1121				}
1122				if strings.Contains(msg, tc.notSub) {
1123					t.Fatalf("stderr=%q, must not contain %q", msg, tc.notSub)
1124				}
1125			})
1126		}
1127	}
