}

func TestCLIEvaluateExtraFieldFailures(t *testing.T) {
	// 附加信息虽不参与求值，仍属于被完整检查的配置：其中的重复字段与无效
	// JSON 都要非零退出、stdout 为空，stderr 指出问题来自配置，且原因能区分
